1661	function applyPowerup(p, type) {
1662	  if (type === PUP_SHIELD) {
1663	    p.hasShield = true;
1664	  } else {
1665	    p.activePowerup = type;
1666	    p.powerupTimer = POWERUP_DURATION;
1667	    if (type === PUP_2X) p.scoreMultiplier = 2;
1668	  }
1669	}
1670	/** 清理对象池：移除距离过远且已失效的对象，防止内存无限增长 */
1671	function cleanupPool(pool, maxSize) {
1672	  let writeIdx = 0;
1673	  for (let i = 0; i < pool.length; i++) {
1674	    const obj = pool[i];
1675	    if (obj.active || obj.dist > -600) {
1676	      pool[writeIdx++] = obj;
1677	    }
1678	  }
1679	  pool.length = writeIdx;
1680	  // 安全阀：超过最大数量时裁剪最老的
1681	  if (pool.length > maxSize) {
1682	    const excess = pool.length - maxSize;
1683	    pool.splice(0, excess);
1684	  }
1685	}
