1687	/** 统一的粒子爆发效果 */
1688	function burstParticles(x, y, count, spreadX, spreadY, vRange, lifeRange, colors) {
1689	  for (let i = 0; i < count; i++) {
1690	    const p = poolGet(G.particles, () => createParticle(0,0,0,0,0,'#fff'));
1691	    p.x = x + (Math.random() - 0.5) * spreadX;
1692	    p.y = y + (Math.random() - 0.5) * spreadY;
1693	    p.vx = (Math.random() - 0.5) * vRange;
1694	    p.vy = (Math.random() - 0.5) * vRange;
1695	    p.life = randInt(lifeRange[0], lifeRange[1]);
1696	    p.maxLife = p.life;
1697	    p.color = randChoice(colors);
1698	    p.size = randInt(2, 5);
1699	  }
1700	}
1701	
1702	/* =========================== 分数弹出文字 =========================== */
1703	function spawnPopup(x, y, text, color) {
1704	  G.popups.push({ x, y, text, color, life: 40, vy: -1.5, alpha: 1 });
1705	}
1706	
1707	function updatePopups() {
1708	  for (let i = G.popups.length - 1; i >= 0; i--) {
1709	    const p = G.popups[i];
1710	    p.y += p.vy;
1711	    p.life--;
1712	    p.alpha = Math.min(1, p.life / 20);
1713	    if (p.life <= 0) G.popups.splice(i, 1);
1714	  }
1715	}
1716	
1717	function renderPopups(ctx) {
1718	  for (let i = 0; i < G.popups.length; i++) {
1719	    const p = G.popups[i];
1720	    ctx.globalAlpha = p.alpha;
1721	    ctx.fillStyle = p.color;
1722	    ctx.font = 'bold 16px "Segoe UI","PingFang SC",sans-serif';
1723	    ctx.textAlign = 'center';
1724	    ctx.shadowColor = 'rgba(0,0,0,0.5)';
1725	    ctx.shadowBlur = 3;
1726	    ctx.fillText(p.text, p.x, p.y);
1727	    ctx.shadowBlur = 0;
1728	  }
1729	  ctx.globalAlpha = 1;
1730	}
1731	
1732	/* =========================== 连击系统 =========================== */
1733	function addCombo(type) {
1734	  G.combo++;
1735	  if (G.combo > G.maxCombo) G.maxCombo = G.combo;
1736	  const bonus = G.combo * 10 * G.player.scoreMultiplier;
1737	  G.coinScore += bonus;
1738	  const px = G.player.x;
1739	  const py = G.player.y - 60;
1740	  if (G.combo >= 5) {
1741	    spawnPopup(px, py, G.combo + 'x COMBO! +' + bonus, '#ffdd00');
1742	  } else if (G.combo >= 3) {
1743	    spawnPopup(px, py, '+' + bonus, '#ffaa00');
1744	  }
1745	}
1746	
1747	function resetCombo() {
1748	  if (G.combo >= 5) {
1749	    spawnPopup(G.player.x, G.player.y - 40, 'COMBO LOST', '#ff4444');
1750	  }
1751	  G.combo = 0;
1752	}
1753	
1754	/* =========================== 渲染 =========================== */
1755	function render() {
1756	  const ctx = G.ctx;
1757	  ctx.clearRect(0, 0, G.W, G.H);
1758	  ctx.save();
1759	  if (G.shakeDuration > 0) {
1760	    ctx.translate(
1761	      (Math.random() - 0.5) * G.shakeX * 2,
1762	      (Math.random() - 0.5) * G.shakeY * 2
1763	    );
1764	  }
1765	  renderBackground(ctx);
1766	  renderEntities(ctx);
1767	  renderParticles(ctx);
1768	  renderPopups(ctx);
1769	  ctx.restore();
1770	  renderEffects(ctx);
1771	  renderUI(ctx);
1772	}
1773	
1774	function renderBackground(ctx) {
1775	  /* 天空 */
1776	  ctx.drawImage(G.offscreen.sky, 0, 0);
1777	  /* 云层（独立慢速视差） */
1778	  const cloudOffset = (G.distance * PARALLAX_CLOUD) % G.offscreen.clouds.width;
1779	  if (cloudOffset + G.W <= G.offscreen.clouds.width) {
1780	    ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, G.W, G.offscreen.clouds.height, 0, 0, G.W, G.offscreen.clouds.height);
1781	  } else {
1782	    const w1 = G.offscreen.clouds.width - cloudOffset;
1783	    ctx.drawImage(G.offscreen.clouds, cloudOffset, 0, w1, G.offscreen.clouds.height, 0, 0, w1, G.offscreen.clouds.height);
1784	    ctx.drawImage(G.offscreen.clouds, 0, 0, G.W - w1, G.offscreen.clouds.height, w1, 0, G.W - w1, G.offscreen.clouds.height);
1785	  }
1786	  /* 远山（最慢视差） */
1787	  const mtnOffset = (G.distance * PARALLAX_MOUNTAIN) % G.offscreen.mountains.width;
1788	  if (mtnOffset + G.W <= G.offscreen.mountains.width) {
1789	    ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, G.W, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, G.W, G.offscreen.mountains.height);
1790	  } else {
1791	    const w1 = G.offscreen.mountains.width - mtnOffset;
1792	    ctx.drawImage(G.offscreen.mountains, mtnOffset, 0, w1, G.offscreen.mountains.height, 0, G.vanishY - G.offscreen.mountains.height + 60, w1, G.offscreen.mountains.height);
1793	    ctx.drawImage(G.offscreen.mountains, 0, 0, G.W - w1, G.offscreen.mountains.height, w1, G.vanishY - G.offscreen.mountains.height + 60, G.W - w1, G.offscreen.mountains.height);
1794	  }
1795	  /* 城市天际线（远景） */
1796	  const cityOffset = (G.distance * PARALLAX_FAR) % (G.W * 3);
1797	  if (cityOffset + G.W <= G.offscreen.city.width) {
1798	    ctx.drawImage(G.offscreen.city, cityOffset, 0, G.W, G.H*0.25, 0, G.vanishY - 30, G.W, G.H*0.25);
1799	  } else {
1800	    const w1 = G.offscreen.city.width - cityOffset;
1801	    ctx.drawImage(G.offscreen.city, cityOffset, 0, w1, G.H*0.25, 0, G.vanishY - 30, w1, G.H*0.25);
1802	    ctx.drawImage(G.offscreen.city, 0, 0, G.W - w1, G.H*0.25, w1, G.vanishY - 30, G.W - w1, G.H*0.25);
1803	  }
1804	  /* 近景建筑 */
1805	  const nearOffset = (G.distance * PARALLAX_NEAR) % (G.W * 2);
1806	  if (nearOffset + G.W <= G.offscreen.nearCity.width) {
1807	    ctx.drawImage(G.offscreen.nearCity, nearOffset, 0, G.W, G.H*0.35, 0, G.vanishY + 10, G.W, G.H*0.35);
1808	  } else {
1809	    const w1 = G.offscreen.nearCity.width - nearOffset;
1810	    ctx.drawImage(G.offscreen.nearCity, nearOffset, 0, w1, G.H*0.35, 0, G.vanishY + 10, w1, G.H*0.35);
1811	    ctx.drawImage(G.offscreen.nearCity, 0, 0, G.W - w1, G.H*0.35, w1, G.vanishY + 10, G.W - w1, G.H*0.35);
1812	  }
1813	  drawGround(ctx);
1814	  drawTracks(ctx);
1815	}
1816	
1817	function renderEntities(ctx) {
1818	  const entities = [];
1819	  for (let i = 0; i < G.obstacles.length; i++) {
1820	    const o = G.obstacles[i];
1821	    if (!o.active) continue;
1822	    entities.push({ type:'obstacle', obj:o, dist:o.dist, lane:o.lane });
1823	  }
1824	  for (let i = 0; i < G.trains.length; i++) {
1825	    const t = G.trains[i];
1826	    if (!t.active) continue;
1827	    entities.push({ type:'train', obj:t, dist:t.dist, lane:t.lane });
1828	  }
1829	  for (let i = 0; i < G.coins.length; i++) {
1830	    const c = G.coins[i];
1831	    if (!c.active || c.collected) continue;
1832	    entities.push({ type:'coin', obj:c, dist:c.dist, lane:c.lane });
1833	  }
1834	  for (let i = 0; i < G.powerups.length; i++) {
1835	    const pu = G.powerups[i];
1836	    if (!pu.active || pu.collected) continue;
1837	    entities.push({ type:'powerup', obj:pu, dist:pu.dist, lane:pu.lane });
1838	  }
1839	  entities.sort((a, b) => b.dist - a.dist);
1840	  const frontEntities = entities.filter(e => e.dist > 0);
1841	  const behindEntities = entities.filter(e => e.dist <= 0);
1842	
1843	  frontEntities.forEach(e => {
1844	    const s = worldToScreen(e.dist);
1845	    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
1846	    const sx = laneX(e.lane, e.dist);
1847	    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
1848	    else if (e.type === 'train') drawTrain(ctx, e.obj, e.lane, e.dist, sx, s.y, s.scale);
1849	    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
1850	    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
1851	  });
1852	  drawPlayer(ctx);
1853	  behindEntities.forEach(e => {
1854	    const s = worldToScreen(e.dist);
1855	    if (s.y < G.vanishY - 20 || s.y > G.H + 60) return;
1856	    const sx = laneX(e.lane, e.dist);
1857	    if (e.type === 'obstacle') drawObstacle(ctx, e.obj, sx, s.y, s.scale);
1858	    else if (e.type === 'train') drawTrain(ctx, e.obj, e.lane, e.dist, sx, s.y, s.scale);
1859	    else if (e.type === 'coin') drawCoin(ctx, e.obj, sx, s.y, s.scale);
1860	    else if (e.type === 'powerup') drawPowerup(ctx, e.obj, sx, s.y, s.scale);
1861	  });
1862	}
1863	
1864	function renderParticles(ctx) {
1865	  for (let i = 0; i < G.particles.length; i++) {
1866	    const p = G.particles[i];
1867	    if (!p.active) continue;
1868	    const alpha = p.life / p.maxLife;
1869	    ctx.globalAlpha = alpha;
1870	    ctx.fillStyle = p.color;
1871	    ctx.fillRect(p.x - p.size/2, p.y - p.size/2, p.size, p.size);
1872	  }
1873	  ctx.globalAlpha = 1;
1874	}
1875	
1876	function renderEffects(ctx) {
1877	  const speedRatio = (G.speed - BASE_SPEED) / (MAX_SPEED - BASE_SPEED);
1878	  if (speedRatio > SPEED_LINE_THRESHOLD && G.state === 'playing') {
1879	    const intensity = (speedRatio - SPEED_LINE_THRESHOLD) * SPEED_LINE_INTENSITY;
1880	    ctx.strokeStyle = `rgba(255,255,255,${intensity * 0.3})`;
1881	    ctx.lineWidth = 1;
1882	    for (let i = 0; i < SPEED_LINE_COUNT; i++) {
1883	      const ly = Math.random() * G.H;
1884	      const lx = Math.random() * G.W;
1885	      const len = 20 + Math.random() * 40 * intensity;
1886	      ctx.beginPath();
1887	      ctx.moveTo(lx, ly);
1888	      ctx.lineTo(lx + len, ly);
1889	      ctx.stroke();
1890	    }
1891	  }
1892	  if (G.flashAlpha > 0) {
1893	    ctx.fillStyle = `rgba(255,40,40,${G.flashAlpha})`;
1894	    ctx.fillRect(0, 0, G.W, G.H);
1895	  }
1896	}
1897	
1898	function renderUI(ctx) {
1899	  drawHUD(ctx);
1900	  if (G.state === 'start') drawStartScreen(ctx);
1901	  if (G.state === 'dead') drawDeathScreen(ctx);
1902	}
1903	
1904	/* =========================== 绘制地面 =========================== */
1905	function drawGround(ctx) {
1906	  const groundTop = G.vanishY + 30;
1907	  const groundBot = G.H;
1908	
1909	  /* 碎石地表渐变 */
1910	  const grad = ctx.createLinearGradient(0, groundTop, 0, groundBot);
1911	  grad.addColorStop(0, '#8b7355');
1912	  grad.addColorStop(0.3, '#9b8b75');
1913	  grad.addColorStop(0.7, '#a09080');
1914	  grad.addColorStop(1, '#b0a090');
1915	  ctx.fillStyle = grad;
1916	  ctx.fillRect(0, groundTop, G.W, groundBot - groundTop);
1917	
1918	  /* 轨道两侧路堤护坡 */
1919	  drawEmbankments(ctx);
1920	
1921	  /* 碎石纹理点 */
1922	  ctx.fillStyle = 'rgba(120,110,100,0.3)';
1923	  const seed = 42;
1924	  for (let y = groundTop; y < groundBot; y += 12) {
1925	    for (let x = 0; x < G.W; x += 14) {
1926	      if (((x * 31 + y * 17 + seed) % 7) === 0) {
1927	        ctx.fillRect(x, y, 2, 2);
1928	      }
1929	    }
1930	  }
1931	
1932	  /* 轨旁景物（电杆、灌木） */
1933	  drawTracksideScenery(ctx);
1934	}
1935	
1936	/* 轨道两侧土堤/植被护坡 */
1937	function drawEmbankments(ctx) {
1938	  for (let lane = 0; lane < LANE_COUNT; lane++) {
1939	    /* 每段距离画护坡梯形 */
1940	    for (let d = 0; d < G.maxDist; d += 80) {
1941	      const s0 = worldToScreen(d);
1942	      const s1 = worldToScreen(d + 80);
1943	      if (s0.y < G.vanishY || s1.y > G.H + 20) continue;
1944	
1945	      const sc0 = Math.max(0.1, s0.scale);
1946	      const sc1 = Math.max(0.1, s1.scale);
1947	
1948	      const lx0 = laneX(lane, d);
1949	      const lx1 = laneX(lane, d + 80);
1950	
1951	      /* 左侧护坡 */
1952	      const lOuter0 = lx0 - 22 * sc0, lOuter1 = lx1 - 22 * sc1;
1953	      ctx.fillStyle = '#6b8e5a';
1954	      ctx.beginPath();
1955	      ctx.moveTo(lOuter0, s0.y);
1956	      ctx.lineTo(lOuter1, s1.y);
1957	      ctx.lineTo(lx1 - 12 * sc1, s1.y);
1958	      ctx.lineTo(lx0 - 12 * sc0, s0.y);
1959	      ctx.closePath();
1960	      ctx.fill();
1961	      /* 坡顶亮线 */
1962	      ctx.strokeStyle = '#7a9e68';
1963	      ctx.lineWidth = 1;
1964	      ctx.beginPath();
1965	      ctx.moveTo(lOuter0, s0.y);
1966	      ctx.lineTo(lOuter1, s1.y);
1967	      ctx.stroke();
1968	
1969	      /* 右侧护坡 */
1970	      const rOuter0 = lx0 + 22 * sc0, rOuter1 = lx1 + 22 * sc1;
1971	      ctx.fillStyle = '#6b8e5a';
1972	      ctx.beginPath();
1973	      ctx.moveTo(lx0 + 12 * sc0, s0.y);
1974	      ctx.lineTo(lx1 + 12 * sc1, s1.y);
1975	      ctx.lineTo(rOuter1, s1.y);
1976	      ctx.lineTo(rOuter0, s0.y);
1977	      ctx.closePath();
1978	      ctx.fill();
1979	      ctx.strokeStyle = '#7a9e68';
1980	      ctx.beginPath();
1981	      ctx.moveTo(rOuter0, s0.y);
1982	      ctx.lineTo(rOuter1, s1.y);
1983	      ctx.stroke();
1984	    }
1985	  }
1986	}
1987	
1988	/* 轨旁景物 */
1989	function drawTracksideScenery(ctx) {
1990	  const poleInterval = 180; // 电杆间距（世界坐标）
1991	
1992	  for (let lane = 0; lane < LANE_COUNT; lane++) {
1993	    for (let d = poleInterval; d < G.maxDist; d += poleInterval) {
1994	      const s = worldToScreen(d);
1995	      if (s.y < G.vanishY + 10 || s.y > G.H + 40) continue;
1996	
1997	      const lx = laneX(lane, d);
1998	      const sc = Math.max(0.08, s.scale);
1999	      const poleH = 35 * sc;
2000	      const poleW = 3 * sc;
2001	
2002	      /* 左侧电杆 */
2003	      const lpx = lx - 28 * sc;
2004	      ctx.fillStyle = '#5a4a3a';
2005	      ctx.fillRect(lpx - poleW/2, s.y - poleH, poleW, poleH);
2006	      /* 杆顶横梁 */
2007	      ctx.fillRect(lpx - 6*sc, s.y - poleH, poleW * 4, poleW);
2008	      /* 瓷瓶 */
2009	      ctx.fillStyle = '#ddd';
2010	      ctx.fillRect(lpx - 5*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
2011	      ctx.fillRect(lpx + 2*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
2012	
2013	      /* 右侧电杆 */
2014	      const rpx = lx + 28 * sc;
2015	      ctx.fillStyle = '#5a4a3a';
2016	      ctx.fillRect(rpx - poleW/2, s.y - poleH, poleW, poleH);
2017	      ctx.fillRect(rpx - 6*sc, s.y - poleH, poleW * 4, poleW);
2018	      ctx.fillStyle = '#ddd';
2019	      ctx.fillRect(rpx - 5*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
2020	      ctx.fillRect(rpx + 2*sc, s.y - poleH - 2*sc, 2*sc, 3*sc);
2021	    }
2022	
2023	    /* 灌木丛（不同间距避免与电杆重叠） */
2024	    for (let d = 60; d < G.maxDist; d += 110) {
2025	      const s = worldToScreen(d);
2026	      if (s.y < G.vanishY + 20 || s.y > G.H + 30) continue;
2027	
2028	      const lx = laneX(lane, d);
2029	      const sc = Math.max(0.08, s.scale);
2030	      const bushR = 5 * sc;
2031	
2032	      /* 随机左右各放灌木 */
2033	      if ((d + lane * 73) % 3 !== 0) {
2034	        const bx = lx + (d % 2 === 0 ? -22 : 22) * sc;
2035	        ctx.fillStyle = '#4a7a3a';
2036	        ctx.beginPath();
2037	        ctx.arc(bx, s.y, bushR, 0, Math.PI * 2);
2038	        ctx.fill();
2039	        ctx.fillStyle = '#5a8a4a';
2040	        ctx.beginPath();
2041	        ctx.arc(bx + 2*sc, s.y - 1*sc, bushR * 0.7, 0, Math.PI * 2);
2042	        ctx.fill();
2043	      }
2044	    }
2045	  }
2046	}
2047	
2048	/* =========================== 绘制轨道 =========================== */
2049	function drawTracks(ctx) {
2050	  for (let lane = 0; lane < LANE_COUNT; lane++) {
2051	    /* 钢轨 */
2052	    const railWidth = 5;
2053	
2054	    /* 左轨 */
2055	    ctx.strokeStyle = '#8899aa';
2056	    ctx.lineWidth = railWidth;
2057	    ctx.beginPath();
2058	    for (let d = 0; d <= G.maxDist; d += 20) {
2059	      const s = worldToScreen(d);
2060	      const lx = laneX(lane, d) - 8;
2061	      if (d === 0) ctx.moveTo(lx, s.y);
2062	      else ctx.lineTo(lx, s.y);
2063	    }
2064	    ctx.stroke();
2065	
2066	    /* 右轨 */
2067	    ctx.beginPath();
2068	    for (let d = 0; d <= G.maxDist; d += 20) {
2069	      const s = worldToScreen(d);
2070	      const rx = laneX(lane, d) + 8;
2071	      if (d === 0) ctx.moveTo(rx, s.y);
2072	      else ctx.lineTo(rx, s.y);
2073	    }
2074	    ctx.stroke();
2075	
2076	    /* 枕木 */
2077	    ctx.strokeStyle = '#6b5b4a';
2078	    ctx.lineWidth = 3;
2079	    for (let d = 20; d < G.maxDist; d += 60) {
2080	      const s = worldToScreen(d);
2081	      const lx = laneX(lane, d);
2082	      ctx.beginPath();
2083	      ctx.moveTo(lx - 10, s.y);
2084	      ctx.lineTo(lx + 10, s.y);
2085	      ctx.stroke();
2086	    }
2087	  }
2088	}
2089	
2090	/* =========================== 绘制障碍物 =========================== */
2091	function drawObstacle(ctx, obs, sx, sy, scale) {
2092	  ctx.save();
2093	  ctx.translate(sx, sy);
2094	  ctx.scale(scale, scale);
2095	
2096	  /* 直接绘制——绕开离屏精灵定位问题 */
2097	  if (obs.type === OBS_LOW) {
2098	    /* 道口横栏（低障碍） */
2099	    /* 支柱 */ ctx.fillStyle = '#555';
2100	    ctx.fillRect(-4, -16, 8, 24); ctx.fillRect(-22, -12, 8, 12); ctx.fillRect(14, -12, 8, 12);
2101	    /* 横杆 */ ctx.fillStyle = '#222';
2102	    ctx.fillRect(-30, -4, 60, 10);
2103	    /* 警示条纹 */ ctx.fillStyle = '#ffcc00';
2104	    ctx.fillRect(-28, -2, 6, 6); ctx.fillRect(-16, -2, 6, 6); ctx.fillRect(-4, -2, 6, 6);
2105	    ctx.fillRect(8, -2, 6, 6); ctx.fillRect(20, -2, 6, 6);
2106	    /* 红白交替 */ ctx.fillStyle = '#ff3333';
2107	    ctx.fillRect(-28, 1, 6, 4); ctx.fillRect(-16, 1, 6, 4); ctx.fillRect(-4, 1, 6, 4);
