2152	function drawTrain(ctx, t, lane, dist, baseSx, baseSy, baseScale) {
2153	  const sc = Math.max(0.15, baseScale);
2154	  const carLen = TRAIN_CAR_LENGTH * sc * 0.18; // 透视缩放
2155	
2156	  for (let car = 0; car < t.carCount; car++) {
2157	    const carDist = dist - car * TRAIN_CAR_LENGTH;
2158	    if (carDist < -100 || carDist > G.maxDist + 200) continue;
2159	
2160	    const s = worldToScreen(carDist);
2161	    const sx = laneX(t.lane, carDist);
2162	    const carH = TRAIN_CAR_HEIGHT * s.scale;
2163	    const carW = carLen * 1.1;
2164	
2165	    /* 车身 */
2166	    const bodyColor = car % 2 === 0 ? '#3a5070' : '#4a6078';
2167	    ctx.fillStyle = bodyColor;
2168	    ctx.fillRect(sx - carW/2, s.y - carH, carW, carH);
2169	
2170	    /* 车厢顶部 */
2171	    ctx.fillStyle = '#5a7088';
2172	    ctx.fillRect(sx - carW/2 + 2*s.scale, s.y - carH, carW - 4*s.scale, 5*s.scale);
2173	
2174	    /* 窗户 */
2175	    const winCount = 3;
2176	    const winW = carW * 0.18;
2177	    const winH = carH * 0.28;
2178	    const winY = s.y - carH * 0.75;
2179	    for (let w = 0; w < winCount; w++) {
2180	      const wx = sx - carW/2 + carW * (0.15 + w * 0.28);
2181	      ctx.fillStyle = '#aaccff';
2182	      ctx.fillRect(wx, winY, winW, winH);
2183	      ctx.fillStyle = 'rgba(255,255,200,0.5)';
2184	      ctx.fillRect(wx + winW*0.2, winY, winW*0.6, winH);
2185	    }
2186	
2187	    /* 底盘 */
2188	    ctx.fillStyle = '#222';
2189	    ctx.fillRect(sx - carW/2 - 2*s.scale, s.y - 2*s.scale, carW + 4*s.scale, 4*s.scale);
2190	
2191	    /* 车轮 */
2192	    ctx.fillStyle = '#111';
2193	    const wheelR = 4 * s.scale;
2194	    for (let wh = 0; wh < 2; wh++) {
2195	      const wx = sx - carW * 0.28 + wh * carW * 0.56;
2196	      ctx.beginPath();
2197	      ctx.arc(wx, s.y + 1*s.scale, wheelR, 0, Math.PI * 2);
2198	      ctx.fill();
2199	      ctx.strokeStyle = '#333';
2200	      ctx.lineWidth = 0.5;
2201	      ctx.stroke();
2202	    }
2203	
2204	    /* 车厢间连接 */
2205	    if (car < t.carCount - 1) {
2206	      ctx.strokeStyle = '#333';
2207	      ctx.lineWidth = 1.5 * s.scale;
2208	      ctx.beginPath();
2209	      ctx.moveTo(sx - carW/2, s.y - carH * 0.3);
2210	      const nextS = worldToScreen(carDist - TRAIN_CAR_LENGTH);
2211	      const nextSx = laneX(t.lane, carDist - TRAIN_CAR_LENGTH);
2212	      ctx.lineTo(nextSx + carLen/2, nextS.y - carH * 0.3);
2213	      ctx.stroke();
2214	    }
2215	  }
2216	}
