2258	function drawPlayer(ctx) {
2259	  const p = G.player;
2260	  const sprites = G.offscreen.player;
2261	  if (!sprites) return;
2262	  ctx.save();
2263	  ctx.translate(p.x, p.y);
2264	
2265	  /* 无敌闪烁 */
2266	  let alpha = 1;
2267	  if (G.invincible > 0 && Math.floor(G.invincible / 4) % 2 === 0) {
2268	    alpha = 0.35;
2269	  }
2270	
2271	  /* 阴影（滑铲时随旋转进度平滑过渡为宽扁椭圆） */
2272	  const sliding = p.state === STATE_SLIDE;
2273	  let shFrac = 0; // 0=正常阴影, 1=滑铲阴影
2274	  if (sliding) {
2275	    const progress = 1 - p.stateTimer / SLIDE_DURATION;
2276	    shFrac = progress < 0.18 ? progress / 0.18
2277	           : progress < 0.75 ? 1
2278	           : Math.max(0, 1 - (progress - 0.75) / 0.25);
2279	  }
2280	  ctx.fillStyle = `rgba(0,0,0,${0.25 + shFrac * 0.10})`;
2281	  ctx.beginPath();
2282	  ctx.ellipse(
2283	    -22 * shFrac,              // x 左移
2284	    12 - 6 * shFrac,           // y 上移
2285	    20 + 15 * shFrac,           // rx 拉宽
2286	    7 - 2 * shFrac,            // ry 压扁
2287	    0, 0, Math.PI * 2
2288	  );
2289	  ctx.fill();
2290	
2291	  /* 选择精灵帧 */
2292	  let frame = sprites.run[0]; // 默认第一帧
2293	  const SW = 80, SH = 100;
2294	
2295	  if (p.state === STATE_RUN) {
2296	    /* 庆祝动画 */
2297	    if (p.celebrateTimer > 0 && p.celebrateType) {
2298	      if (p.celebrateType === 'lookback') {
2299	        frame = sprites.lookback;
2300	      } else if (p.celebrateType === 'kick') {
2301	        frame = p.celebrateTimer > 15 ? sprites.kick : sprites.run[Math.floor(G.frameCount / 8) % 8];
2302	      }
2303	    } else {
2304	      /* 8帧跑步循环 ~7.5fps */
2305	      frame = sprites.run[Math.floor(G.frameCount / 8) % 8];
2306	    }
2307	  } else if (p.state === STATE_JUMP) {
2308	    /* 4阶段跳跃动画：预蹲(0.25s)→腾空(1.0s)→下落(0.7s)→落地(0.55s) */
2309	    const t = p.stateTimer;
2310	    if (t > 135)        frame = sprites.jump[0];  // 预蹲蓄力
2311	    else if (t > 75)    frame = sprites.jump[1];  // 腾空上升
2312	    else if (t > 33)    frame = sprites.jump[2];  // 下落
2313	    else                frame = sprites.jump[3];  // 落地缓冲
2314	  } else if (p.state === STATE_SLIDE) {
2315	    /* 6阶段滑铲：下蹲→前倾→俯冲→贴地1→贴地2→起身，旋转角平滑过渡 */
2316	    const t = p.stateTimer;
2317	    if (t > 85)         frame = sprites.slide[0]; // 下蹲
2318	    else if (t > 68)    frame = sprites.slide[1]; // 前倾
2319	    else if (t > 50)    frame = sprites.slide[2]; // 俯冲
2320	    else if (t > 32)    frame = sprites.slide[3]; // 贴地1
2321	    else if (t > 16)    frame = sprites.slide[4]; // 贴地2
2322	    else                frame = sprites.slide[5]; // 起身
2323	  } else if (p.state === STATE_HIT) {
2324	    frame = sprites.hit;
2325	  }
2326	
2327	  /* 绘制精灵（居中，底部对齐到地面） */
2328	  if (alpha < 1) ctx.globalAlpha = alpha;
2329	
2330	  if (p.state === STATE_SLIDE) {
2331	    /* 平滑旋转：progress 0→0.2 快速下潜, 0.2→0.75 保持-90°, 0.75→1 缓升恢复 */
2332	    const progress = 1 - p.stateTimer / SLIDE_DURATION;
2333	    let rot;
2334	    if (progress < 0.18) {
2335	      rot = -Math.PI / 2 * (1 - Math.pow(1 - progress / 0.18, 3)); // ease-out 下潜
2336	    } else if (progress < 0.75) {
2337	      rot = -Math.PI / 2; // 保持贴地
2338	    } else {
2339	      rot = -Math.PI / 2 * Math.pow(1 - (progress - 0.75) / 0.25, 3); // ease-in 起身
2340	    }
2341	    const frac = Math.abs(rot) / (Math.PI / 2); // 0=直立, 1=水平
2342	    const sy = -92 + frac * 27;                  // 位置插值: -92(直立) → -65(水平)
2343	
2344	    ctx.save();
2345	    ctx.rotate(rot);
2346	    ctx.drawImage(frame, -40, sy);
2347	    if (frac > 0.4) {
2348	      /* 高速运动线（仅大幅旋转时） */
2349	      ctx.strokeStyle = 'rgba(255,255,255,0.18)';
2350	      ctx.lineWidth = 1;
2351	      for (let i = 0; i < 2; i++) {
2352	        ctx.beginPath();
2353	        ctx.moveTo(-5 + i * 15, sy + 20);
2354	        ctx.lineTo(-5 + i * 15, sy + 35);
2355	        ctx.stroke();
2356	      }
2357	    }
2358	    ctx.restore();
2359	  } else {
2360	    ctx.drawImage(frame, -SW / 2, -SH + 8);
2361	  }
2362	
2363	  if (alpha < 1) ctx.globalAlpha = 1;
2364	
2365	  ctx.restore();
2366	}
