2536	  ctx.font = '16px "Segoe UI","PingFang SC",sans-serif';
2537	  ctx.fillText('距离: ' + Math.floor(G.distance) + ' 米', G.W/2, panelY + 108);
2538	
2539	  /* 最高连击 */
2540	  if (G.maxCombo > 0) {
2541	    ctx.fillStyle = '#ffaa00';
2542	    ctx.font = 'bold 16px "Segoe UI","PingFang SC",sans-serif';
2543	    ctx.fillText('最高连击: ' + G.maxCombo + 'x', G.W/2, panelY + 130);
2544	  }
2545	
2546	  /* 最高分 */
2547	  const isNew = G.score >= G.highScore && G.highScore > 0;
2548	  ctx.fillStyle = isNew ? '#ffdd44' : '#aaa';
2549	  ctx.font = 'bold 18px "Segoe UI","PingFang SC",sans-serif';
2550	  ctx.fillText((isNew ? '新纪录！' : '最高分: ') + G.highScore, G.W/2, panelY + 158);
2551	
2552	  /* 重来提示 */
2553	  const alpha = 0.5 + 0.5 * Math.sin(G.frameCount * 0.06);
2554	  ctx.fillStyle = `rgba(255,255,255,${alpha})`;
2555	  ctx.font = '18px "Segoe UI","PingFang SC",sans-serif';
2556	  ctx.fillText('点击屏幕 或 按空格键 重来', G.W/2, panelY + panelH + 40);
2557	}
2558	
2559	function roundRect(ctx, x, y, w, h, r) {
2560	  ctx.beginPath();
2561	  ctx.moveTo(x + r, y);
2562	  ctx.lineTo(x + w - r, y);
2563	  ctx.quadraticCurveTo(x + w, y, x + w, y + r);
2564	  ctx.lineTo(x + w, y + h - r);
2565	  ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
2566	  ctx.lineTo(x + r, y + h);
2567	  ctx.quadraticCurveTo(x, y + h, x, y + h - r);
2568	  ctx.lineTo(x, y + r);
2569	  ctx.quadraticCurveTo(x, y, x + r, y);
2570	  ctx.closePath();
2571	}
2572	
2573	/* =========================== 游戏主循环 =========================== */
2574	function gameLoop(timestamp) {
2575	  G.deltaTime = timestamp - G.lastTime;
2576	  G.lastTime = timestamp;
2577	
2578	  /* FPS 计算 */
2579	  G.frameCount++;
2580	  G.fpsFrameCount++;
2581	  G.fpsTime += G.deltaTime;
2582	  if (G.fpsTime >= 1000) {
2583	    G.fps = G.fpsFrameCount;
2584	    G.fpsFrameCount = 0;
2585	    G.fpsTime = 0;
2586	  }
2587	
2588	  processInput();
2589	  update();
2590	  render();
2591	  requestAnimationFrame(gameLoop);
2592	}
2593	
2594	/* =========================== 启动 =========================== */
2595	init();
2596	</script>
